InterfaceAsPlainText.xhtml:
TYPE ST_Recipe :
STRUCT
    rRatio : REAL := 0.02;
    tMix : TIME := T#500MS;
    sName : STRING(20) := 'NaOCl';
END_STRUCT
END_TYPE

TYPE U_RawWord :
UNION
    wRaw : WORD;
    abByte : ARRAY[0..1] OF BYTE;
END_UNION
END_TYPE

ST.xhtml:
IF rMin <= rMax THEN
    rLo := rMin;
    rHi := rMax;
ELSE
    rLo := rMax;
    rHi := rMin;
END_IF
F_Clamp := LIMIT(rLo, rIn, rHi);

InterfaceAsPlainText.xhtml:
// Ограничение значения пределами; пределы, заданные наоборот, меняются местами
FUNCTION F_Clamp : REAL
VAR_INPUT
    rIn : REAL;
    rMin : REAL;
    rMax : REAL;
END_VAR
VAR
    rLo : REAL;
    rHi : REAL;
END_VAR

ST.xhtml:
IF iRaw < 0 OR iRaw > 27648 THEN
    xFault := TRUE;
ELSE
    xFault := FALSE;
    rValue := F_Clamp(rIn := rLo + (rHi - rLo) * INT_TO_REAL(iRaw) / 27648.0, rMin := rLo, rMax := rHi);
END_IF

InterfaceAsPlainText.xhtml:
// Масштабирование 0..27648 → rLo..rHi; вне диапазона — неисправность, значение удерживается
FUNCTION_BLOCK FB_AnalogScale
VAR_INPUT
    iRaw : INT;
    rLo : REAL := 0.0;
    rHi : REAL := 100.0;
END_VAR
VAR_OUTPUT
    rValue : REAL;
    xFault : BOOL;
END_VAR

ST.xhtml:
IF xReset THEN
    rTotal_m3 := 0.0;
ELSIF rFlow_m3h > 0.0 THEN
    rTotal_m3 := rTotal_m3 + rFlow_m3h * TIME_TO_REAL(tCycle) / 3600000.0;
END_IF
diPulses := REAL_TO_DINT(rTotal_m3);

InterfaceAsPlainText.xhtml:
// Интегрирование расхода (м3/ч) по времени цикла; сброс уровнем; импульсы — округление до целого (REAL_TO_DINT)
FUNCTION_BLOCK FB_FlowTotal
VAR_INPUT
    rFlow_m3h : REAL;
    tCycle : TIME := T#100MS;
    xReset : BOOL;
END_VAR
VAR_OUTPUT
    rTotal_m3 : REAL;
    diPulses : DINT;
END_VAR

ST.xhtml:
fbTon(IN := xStart, PT := T#150MS);
xQ := fbTon.Q;
tEt := fbTon.ET;

InterfaceAsPlainText.xhtml:
// TON 150 мс: на нём видно квантование таймера периодом задачи (MS-EXEC-01)
PROGRAM PRG_TonQuant
VAR_INPUT
    xStart : BOOL;
END_VAR
VAR_OUTPUT
    xQ : BOOL;
    tEt : TIME;
END_VAR
VAR
    fbTon : TON;
END_VAR

ST.xhtml:
fbScale(iRaw := GVL_IO.iFlowRaw, rLo := 0.0, rHi := 120.0);
fbTotal(rFlow_m3h := fbScale.rValue, tCycle := T#10MS);
GVL_Retain.rTotalDosed := fbTotal.rTotal_m3;
GVL_IO.xPumpOut S= eState = E_DoseState.Dosing;
GVL_IO.xPumpOut R= GVL_IO.xLevelLow;
CASE eState OF
    E_DoseState.Idle:
        IF NOT GVL_IO.xLevelLow THEN
            eState := E_DoseState.Priming;
            dtLastStart := DT#1970-01-01-00:00:00;
        END_IF
    E_DoseState.Priming:
        eState := E_DoseState.Dosing;
    E_DoseState.Dosing:
        IF GVL_IO.xLevelLow THEN
            eState := E_DoseState.Idle;
        END_IF
ELSE
    eState := E_DoseState.Fault;
END_CASE
ltUptime := ltUptime + LTIME#10MS;
sMsg := stRecipe.sName;
rLevel_ := fbScale.rValue;
pRaw := ADR(iStep);
IF iStep > 3 THEN
    JMP lblEnd;
END_IF
iStep := iStep + 1;
lblEnd:
;

