// Главная программа УДР-1: вызовы и конструкции диалекта, которые перенос меняет
PROGRAM PRG_Main
VAR
    fbScale : FB_AnalogScale;
    fbTotal : FB_FlowTotal;
    eState : E_DoseState := E_DoseState.Idle;
    stRecipe : ST_Recipe;
    sMsg : STRING(40);
    ltUptime : LTIME;
    dtLastStart : DT;
    rLevel_ : REAL;
    iStep : INT;
    pRaw : POINTER TO INT;
END_VAR

ST.xhtml:
IF xRunning THEN
    udiTicks := udiTicks + 1;
END_IF

InterfaceAsPlainText.xhtml:
// Базовый ФБ устройства: пуск, останов, счёт тиков в работе
FUNCTION_BLOCK FB_DeviceBase
VAR_OUTPUT
    xRunning : BOOL;
    udiTicks : UDINT;
END_VAR
VAR
    iState : INT;
END_VAR

ST.xhtml:
SUPER^();
IF xRunning THEN
    rDosed_ml := rDosed_ml + rStroke_ml;
END_IF

IF xRunning THEN
    rTotal_ml := rTotal_ml + rAmount_ml;
    Dose := TRUE;
ELSE
    Dose := FALSE;
END_IF

InterfaceAsPlainText.xhtml:
// Насос-дозатор: наследует FB_DeviceBase, реализует I_Device; доза — метод с VAR_IN_OUT
FUNCTION_BLOCK FB_DosingPump EXTENDS FB_DeviceBase IMPLEMENTS I_Device
VAR_INPUT
    rStroke_ml : REAL := 0.5;
END_VAR
VAR_OUTPUT
    rDosed_ml : REAL;
END_VAR

ST.xhtml:
itfDev := fbPump;
IF xRun AND NOT fbPump.xRunning THEN
    xOk := itfDev.Start();
END_IF
IF xStop THEN
    fbPump.Stop();
END_IF
fbPump(rStroke_ml := 0.5);
xOk := fbPump.Dose(rAmount_ml := 0.25, rTotal_ml := rTotal_ml);
iState := fbPump.State;
iLoops := 0;
WHILE fbPump.NeedsMore(rTarget_ml := 2.0) AND iLoops < 3 DO
    fbPump(rStroke_ml := 0.5);
    iLoops := iLoops + 1;
END_WHILE
rPumped_ml := fbPump.Dosed;

InterfaceAsPlainText.xhtml:
// Вызовы методов экземпляра, интерфейсная переменная, свойство, метод в условии WHILE
PROGRAM PRG_OopDemo
VAR_INPUT
    xRun : BOOL;
    xStop : BOOL;
END_VAR
VAR_OUTPUT
    rTotal_ml : REAL;
    iState : INT;
    rPumped_ml : REAL;
    iLoops : INT;
END_VAR
VAR
    fbPump : FB_DosingPump;
    itfDev : I_Device;
    xOk : BOOL;
END_VAR

